    RequestUri = new Uri("https://api.procore.com/rest/v2.0/companies/%7Bcompany_id%7D/projects/%7Bproject_id%7D/links/bulk_update"),
    Content = new StringContent("[{\"id\":\"999\",\"title\":\"Site cam\",\"url\":\"https://developers.procore.com/reference/authentication\"}]")
